\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={60}{30},
    xlabel={$x$},
    ylabel={$y$},
    zlabel={$z$},
    title={Elliptic Cone: $9x^2 - y^2 + z^2 = 0$},
    width=12cm,
    height=10cm,
    domain=-2:2,
    y domain=-3:3,
    samples=30,
    samples y=20,
    colormap/viridis,
    axis lines=center,
    enlargelimits=0.15,
    grid=major,
    legend style={at={(0.9,0.1)},anchor=south east},
]

% The elliptic cone surface
\addplot3[surf, opacity=0.6] ({abs(y)/3*cos(deg(x))}, {y}, {abs(y)*sin(deg(x))});

% Trace at y = 2 (ellipse)
\addplot3[domain=0:360, samples=50, thick, red] 
    ({2/3*cos(deg(x))}, {2}, {2*sin(deg(x))});
\addlegendentry{Ellipse at $y=2$}

% Trace lines at z = 0
\addplot3[domain=-1.5:1.5, samples=20, thick, blue] (x, {3*x}, 0);
\addlegendentry{Lines at $z=0$}

\end{axis}
\end{tikzpicture}
\end{document}

\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\usepgfplotslibrary{colormaps}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={$x$},
    ylabel={$y$},
    title={Cross-sections of Elliptic Cone in X-Y Plane},
    width=10cm,
    height=8cm,
    axis lines=center,
    enlargelimits=0.15,
    grid=major,
    legend style={at={(0.95,0.95)},anchor=north east},
    xmin=-2, xmax=2,
    ymin=-4, ymax=4,
]

% The cone boundary lines y = 3|x| and y = -3|x|
\addplot[domain=0:2, samples=50, thick, blue] (x, {3*x});
\addplot[domain=-2:0, samples=50, thick, blue] (x, {-3*x});
\addplot[domain=0:2, samples=50, thick, blue] (x, {-3*x});
\addplot[domain=-2:0, samples=50, thick, blue] (x, {3*x});
\addlegendentry{Cone boundaries $y = \pm 3|x|$}

% Ellipse traces at different y values
\addplot[domain=0:360, samples=50, thick, red] ({2/3*cos(deg(x))}, {2 + 2*sin(deg(x))});
\addlegendentry{Ellipse at $y=2$}

\addplot[domain=0:360, samples=50, thick, green] ({1/3*cos(deg(x))}, {1 + 1*sin(deg(x))});
\addlegendentry{Ellipse at $y=1$}

\addplot[domain=0:360, samples=50, thick, purple] ({2/3*cos(deg(x))}, {-2 - 2*sin(deg(x))});
\addlegendentry{Ellipse at $y=-2$}

% Fill the cone region
\addplot[domain=-2:2, samples=100, fill=blue!10, draw=none] (x, {3*abs(x)});
\addplot[domain=-2:2, samples=100, fill=blue!10, draw=none] (x, {-3*abs(x)});

\end{axis}
\end{tikzpicture}
\end{document}

